// Светодиод на D9 через резистор 220 Ом.

const int LED = 9;

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
  Serial.println("Три коротких, один длинный");
}

void loop() {
  for (int i = 0; i < 3; i++) {
    digitalWrite(LED, HIGH);
    delay(250);
    digitalWrite(LED, LOW);
    delay(250);
  }
  digitalWrite(LED, HIGH);
  delay(1200);
  digitalWrite(LED, LOW);
  delay(1200);
}

// Кнопка между D2 и землёй, внутри включена подтяжка к 5 В.
// Нажмите кнопку мышью — светодиод на D9 загорится.

const int BUTTON = 2;
const int LED = 9;

void setup() {
  pinMode(BUTTON, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
  Serial.println("Нажмите кнопку на схеме");
}

void loop() {
  bool pressed = digitalRead(BUTTON) == LOW;
  digitalWrite(LED, pressed ? HIGH : LOW);
  if (pressed) {
    Serial.println("нажата");
    delay(200);
  }
  delay(50);
}

// Крутите ручку потенциометра — меняется яркость светодиода.
// Включите осциллограф (кнопка в шапке схемы) и поставьте развёртку 2 мс/дел:
// на D9 видно настоящий ШИМ.

void setup() {
  pinMode(9, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int value = analogRead(A0);
  int level = map(value, 0, 1023, 0, 255);
  analogWrite(9, level);

  Serial.print("A0 = ");
  Serial.print(value);
  Serial.print("  ->  ШИМ ");
  Serial.println(level);

  delay(300);
}

// Классика: R = 10 кОм, C = 100 мкФ. Постоянная времени τ = R·C = 1 с.
// D9 заряжает конденсатор 3 секунды, потом разряжает. Смотрите осциллограф
// на канале A0: кривая заряда — это и есть экспонента.

void setup() {
  pinMode(9, OUTPUT);
  pinMode(A0, INPUT);
  Serial.begin(9600);
  Serial.println("Заряд/разряд RC-цепи");
}

void loop() {
  digitalWrite(9, HIGH);
  Serial.print("заряд, напряжение: ");
  delay(1000);
  Serial.println(analogRead(A0));

  delay(2000);

  digitalWrite(9, LOW);
  Serial.print("разряд, напряжение: ");
  delay(1000);
  Serial.println(analogRead(A0));

  delay(2000);
}

// Подключение библиотеки по имени работает как в Arduino IDE.
// Вал сервопривода на схеме будет поворачиваться.

#include <Servo.h>

Servo myservo;

void setup() {
  myservo.attach(9);
  Serial.begin(9600);
  Serial.println("Серво: 0 → 180 → 0");
}

void loop() {
  for (int angle = 0; angle <= 180; angle += 10) {
    myservo.write(angle);
    delay(80);
  }
  for (int angle = 180; angle >= 0; angle -= 10) {
    myservo.write(angle);
    delay(80);
  }
  Serial.println("полный оборот");
}

