// DHT11: значения заданы у детали (24 °C и 45 %) — двойной клик меняет их.
// (Протокол не эмулируется побитово: библиотека берёт значения у детали.)

#include <DHT.h>
DHT dht(2);

void setup() {
  Serial.begin(9600);
  dht.begin();
  Serial.println("DHT11 запущен");
}

void loop() {
  float t = dht.readTemperature();
  float h = dht.readHumidity();
  Serial.print("T = ");
  Serial.print(t);
  Serial.print(" C,  H = ");
  Serial.print(h);
  Serial.println(" %");
  delay(1000);
}

// HC-SR04: pulseIn возвращает длительность эха (58 мкс на сантиметр).
// Тяните дальномер по вертикали — расстояние меняется.

const int TRIG = 7;
const int ECHO = 8;

void setup() {
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  Serial.begin(9600);
}

void loop() {
  digitalWrite(TRIG, HIGH);
  delay(10);
  digitalWrite(TRIG, LOW);

  long us = pulseIn(ECHO, HIGH);
  long cm = us / 58;

  Serial.print("эхо ");
  Serial.print(us);
  Serial.print(" мкс -> ");
  Serial.print(cm);
  Serial.println(" см");
  delay(500);
}

