// ESP32: питание 3,3 В, АЦП от 0 до 4095, встроенный светодиод на GPIO2.
// Порт Serial работает через USB-UART, как на плате.

void setup() {
  Serial.begin(115200);
  pinMode(2, OUTPUT);
  pinMode(4, OUTPUT);
  Serial.println("ESP32 запущен");
}

void loop() {
  int raw = analogRead(32);          // 0…4095, а не 0…1023
  int level = map(raw, 0, 4095, 0, 255);
  analogWrite(4, level);

  digitalWrite(2, raw > 2048 ? HIGH : LOW);

  Serial.print("GPIO32 = ");
  Serial.print(raw);
  Serial.print("  ->  LED ");
  Serial.println(level);
  delay(300);
}

