// Два светодиода на D9 и D10 мигают по очереди — «перекрёсток».
// Каждому светодиоду нужен свой резистор: 220 Ом.

void setup() {
  pinMode(9, OUTPUT);
  pinMode(10, OUTPUT);
}

void loop() {
  digitalWrite(9, HIGH);
  digitalWrite(10, LOW);
  delay(400);

  digitalWrite(9, LOW);
  digitalWrite(10, HIGH);
  delay(400);
}

// Одно нажатие включает светодиод, второе — выключает.
// Состояние храним в переменной, а «дребезг» гасим паузой 30 мс.

int state = HIGH;      // с чего начинаем
int last = HIGH;       // что было на выводе в прошлый раз

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(9, OUTPUT);
  digitalWrite(9, state);
  Serial.begin(9600);
  Serial.println("нажмите кнопку");
}

void loop() {
  int now = digitalRead(2);
  if (last == HIGH && now == LOW) {      // поймали момент нажатия
    state = !state;
    digitalWrite(9, state);
    Serial.println(state ? "включено" : "выключено");
  }
  last = now;
  delay(30);
}

// ШИМ (analogWrite) — это быстрое включение-выключение вывода.
// Меняем скважность от 0 до 255 и обратно: светодиод «дышит».

int brightness = 0;
int step = 5;

void setup() {
  pinMode(9, OUTPUT);
}

void loop() {
  analogWrite(9, brightness);
  brightness = brightness + step;
  if (brightness >= 255) step = -5;
  if (brightness <= 0) step = 5;
  delay(20);
}

// Делитель напряжения: фоторезистор сверху, резистор 10 кОм снизу.
// Чем темнее — тем больше сопротивление фоторезистора и меньше напряжение на A0.

void setup() {
  pinMode(9, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int light = analogRead(A0);          // 0 — темно, 1023 — ярко
